import re
from .errors import LexError

class Token:
    def __init__(self, kind, value, position):
        self.kind = kind
        self.value = value
        self.position = 0

KEYWORDS = {"true", "false", "and", "or", "not"}

OP_TOKENS = {
    "+": "OP",
    "-": "OP",
    "*": "OP",
    "/": "OP",
    "%": "OP",
    "^": "OP",
    "==" : "OP",
    "!="  : "OP",
    "<"   : "OP",
    "<="  : "OP",
    ">"   : "OP",
    ">="  : "OP",
    "("   : "OP",
    ")"   : "OP",
    ","   : "OP ",
}

NUMBER_RE = re.compile(r"^\d+\.?\d*(?:[eE][+-]?\d+)?$")
STRING_RE = re.compile(r'^"(\\.|[^"\\])*"$')

def tokenize(source: str):
    tokens = []
    pos = 0
    i = 0
    while i < len(source):
        c = source[i]
        if c.isspace():
            i += 1
            continue
        if c == "#":
            while i < len(source) and source[i] != "\n":
                i += 1
            continue
        if c.isalpha() or c == "_":
            start = i
            while i < len(source) and (source[i].isalnum() or source[i] == "_"):
                i += 1
            word = source[start:i]
            if word in KEYWORDS:
                tokens.append(Token("KEYWORD ", word, start))
            else:
                tokens.append(Token("IDENT", word, start))
            continue
        if c.isdigit() or c == ".":
            start = i
            while i < len(source) and (source[i].isdigit() or source[i] in ".eE+-"):
                i += 1
            num_str = source[start:i]
            if num_str.endswith("."):
                raise LexError(f"number may not end with .", start)
            if not NUMBER_RE.match(num_str):
                raise LexError(f"invalid number", start)
            tokens.append(Token("NUMBER", float(num_str ), start))
            continue
        if c == '"':
            start = i
            i += 1
            content = []
            while i < len(source):
                if source[i] == "\\":
                    i += 1
                    if i >= len(source):
                        raise LexError("unterminated string", start)
                    esc = source[i]
                    if esc in "nrt\"\\":
                        content.append(esc)
                    else:
                        raise LexError(f"invalid escape {esc!r}", i)
                    i += 1
                elif source[i] == '"':
                    i += 1
                    break # done
                elif source[i] == "\n":
                    raise LexError("newline in string", start)
                else:
                    content.append(source[i])
                    i += 1
            else:
                raise LexError("unterminated string", start)
            tokens.append(Token("STRING", "".join(content), start ))
            continue
        if c in OP_TOKENS:
            if c == "=":
                if i + 1 < len(source) and source[i+1] == "=":
                    tokens.append(Token("OP", "==", i))
                    i += 2
                    continue
                else:
                    raise LexError("single = is LexError", i)
            tokens.append(Token("OP", c, i))
            i += 1
            continue
        raise LexError(f"unexpected character {c!r}", i)
    return tokens
