    "*": "OP",
    "/": "OP",
    "%": "OP",
    "^": "OP",
    "==" : "OP",
    "!="  : "OP",
    "<"   : "OP",
    "<="  : "OP",
    ">"   : "OP",
    ">="  : "OP",
    "("   : "OP",
    ")"   : "OP",
    ","   : "OP ",
}

NUMBER_RE = re.compile(r"^\d+\.?\d*(?:[eE][+-]?\d+)?$")
STRING_RE = re.compile(r'^"(\\.|[^"\\])*"$')

def tokenize(source: str):
    tokens = []
    pos = 0
    i = 0
    while i < len(source):
        c = source[i]
        if c.isspace():
            i += 1
            continue
        if c == "#":
            while i < len(source) and source[i] != "\n":
                i += 1
            continue
        if c.isalpha() or c == "_":
            start = i
            while i < len(source) and (source[i].isalnum() or source[i] == "_"):
                i += 1
            word = source[start:i]
            if word in KEYWORDS:
